    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    seeds = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] != bg and 0 < r < h-1 and 0 < c < w-1
             and sum(grid[rr][cc] == grid[r][c]
                     for rr in range(max(0,r-1), min(h,r+2))
                     for cc in range(max(0,c-1), min(w,c+2))) == 1]
    for r, c in seeds:
        color = grid[r][c]
        # Prefer an aligned non-background boundary on the same row/column.
        targets = []
        if grid[r][0] != bg: targets.append((c, -1, 0))
        if grid[r][w-1] != bg: targets.append((w-1-c, 1, 0))
        if grid[0][c] != bg: targets.append((r, 0, -1))
        if grid[h-1][c] != bg: targets.append((h-1-r, 0, 1))
