        _, dc, dr = min(targets)
        rr, cc = r, c
        while 0 <= rr+dr < h and 0 <= cc+dc < w:
            rr += dr; cc += dc
            if grid[rr][cc] != bg:
                break
            out[rr][cc] = color
        out[r][c] = 4
    return out
